#include "continuous_motion_learner.h"
#include <string.h>
void continuous_motion_learner_init(continuous_motion_learner_t*l,float a){memset(l,0,sizeof(*l));kinematic_estimator_init(&l->estimator,a);learned_motion_model_reset(&l->working);}void continuous_motion_learner_start(continuous_motion_learner_t*l){learned_motion_model_reset(&l->working);l->estimator.initialized=false;l->active=true;}void continuous_motion_learner_add(continuous_motion_learner_t*l,motion_vec2_t p,uint64_t t){if(l->active){motion_state2_t s=kinematic_estimator_update(&l->estimator,p,t);learned_motion_model_observe(&l->working,&s);}}bool continuous_motion_learner_stop(continuous_motion_learner_t*l,learned_motion_model_t*out){if(!l->active||!out)return false;l->active=false;*out=l->working;return true;}
